<?php
 namespace Slim\Middleware; class SessionCookie extends \Slim\Middleware { protected $settings; public function __construct($settings = array()) { $defaults = array( 'expires' => '20 minutes', 'path' => '/', 'domain' => null, 'secure' => false, 'httponly' => false, 'name' => 'slim_session', ); $this->settings = array_merge($defaults, $settings); if (is_string($this->settings['expires'])) { $this->settings['expires'] = safe_strtotime($this->settings['expires']); } ini_set('session.use_cookies', 0); session_cache_limiter(false); session_set_save_handler( array($this, 'open'), array($this, 'close'), array($this, 'read'), array($this, 'write'), array($this, 'destroy'), array($this, 'gc') ); } public function call() { $this->loadSession(); $this->next->call(); $this->saveSession(); } protected function loadSession() { if (session_id() === '') { session_start(); } $value = $this->app->getCookie($this->settings['name']); if ($value) { $value = safe_json_decode($value, true); $_SESSION = is_array($value) ? $value : array(); } else { $_SESSION = array(); } } protected function saveSession() { $value = json_encode($_SESSION); if (safe_strlen($value) > 4096) { $this->app->getLog()->error('WARNING! Slim\Middleware\SessionCookie data size is larger than 4KB. Content save failed.'); } else { $this->app->setCookie( $this->settings['name'], $value, $this->settings['expires'], $this->settings['path'], $this->settings['domain'], $this->settings['secure'], $this->settings['httponly'] ); } } public function open($savePath, $sessionName) { return true; } public function close() { return true; } public function read($id) { return ''; } public function write($id, $data) { return true; } public function destroy($id) { return true; } public function gc($maxlifetime) { return true; } } 